PAGES = [
    ("index.html", "zh/index.html", INDEX),
    ("robobrain/index.html", "zh/robobrain/index.html", DIAGRAM_PAGE + ROBOBRAIN),
    ("prefmem/index.html", "zh/prefmem/index.html", DIAGRAM_PAGE + PREFMEM),
]

ATTRS = ("alt", "title", "aria-label", "content", "data-title", "data-body", "data-label", "data-tip", "placeholder")
ENGLISH_RUN = re.compile(r"\b[A-Za-z][a-z']+(?:[\s,;:–-]+[A-Za-z][a-z']+){3,}")
ALLOWED = ["device-width, initial-scale", "Yuliang Gai, Ji Hao", "Minghao Li, Shengcheng Yang", "Robotic Test-time Advancement Policy", "Alexandria Engineering Journal", "Journal of Grid Computing",
           "FT International Engineering and Technology Challenge", "Kimi K3 on Ollama Cloud", "Last known",
           "Cancer diagnosis in smart healthcare", "Optimisation of the MamCancerX model", "multiple instance learning framework",
           "Markovian with Federated Deep Recurrent Neural Network", "to Improve Healthcare in Smart Cities"]


class Leftovers(HTMLParser):
    def __init__(self):
        super().__init__()
        self.found, self.skip = [], 0

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self.skip += 1
        for name, value in attrs:
            if name in ATTRS and value:
                self.check(value)

    def handle_endtag(self, tag):
        if tag in ("script", "style"):
            self.skip -= 1

    def handle_data(self, data):
        if not self.skip:
            self.check(data)

    def check(self, text):
        for allowed in ALLOWED:
            text = text.replace(allowed, "")
        for match in ENGLISH_RUN.findall(text):
            self.found.append(match)


def build():
    missing = []
    for src, dst, pairs in PAGES:
        html = (ROOT / src).read_text(encoding="utf-8")
        for en, zh in COMMON + pairs:
            if en not in html:
                missing.append(f"{src}: {en[:90]}")
                continue
            html = html.replace(en, zh)
        # one level deeper: shared assets and config move up a directory
        if src == "index.html":
            html = re.sub(r'(\s(?:href|src|poster|data-src|data-poster)=")assets/', r"\1../assets/", html)
        else:
            html = html.replace('"../assets/', '"../../assets/').replace('"../config.js"', '"../../config.js"')
        out = ROOT / dst
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(html, encoding="utf-8")
        checker = Leftovers()
        checker.feed(html)
        for leftover in checker.found:
            print(f"  English left in {dst}: {leftover}")
    if missing:
        print("These English fragments were not found. Update their translations in tools/build_zh.py:")
        print("\n".join("  " + m for m in missing))
        sys.exit(1)
    print("Built zh/index.html, zh/robobrain/index.html and zh/prefmem/index.html")


if __name__ == "__main__":
    build()
